import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'

import api from 'lib/api'
import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'

import { escapePath } from '~/layout/panel-layout/ProjectTree/utils'

import { fileSystemTypeParams } from './analyticsFeed'
import { AnalyticsSpace, analyticsSpacesLogic } from './analyticsSpacesLogic'
import { AnalyticsType } from './analyticsUtils'

export interface ShareToSpaceTarget {
    type: AnalyticsType
    ref: string
    name: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface analyticsShareLogicValues {
    spaces: AnalyticsSpace[] // analyticsSpacesLogic
    spacesLoading: boolean // analyticsSpacesLogic
    sharing: boolean
    target: ShareToSpaceTarget | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface analyticsShareLogicActions {
    loadSpaces: (_?: void | undefined) => void // analyticsSpacesLogic
    closeShareToSpace: () => {
        value: true
    }
    openShareToSpace: (target: ShareToSpaceTarget) => {
        target: ShareToSpaceTarget
    }
    shareToSpace: (space: AnalyticsSpace) => {
        space: AnalyticsSpace
    }
    shareToSpaceDone: () => {
        value: true
    }
}

export type analyticsShareLogicType = MakeLogicType<analyticsShareLogicValues, analyticsShareLogicActions>

/** Moves an analysis into a space, so the people in that space find it from the Analyses pane. */
export const analyticsShareLogic = kea<analyticsShareLogicType>([
    path(['scenes', 'analytics', 'analyticsShareLogic']),
    connect(() => ({
        values: [analyticsSpacesLogic, ['spaces', 'spacesLoading']],
        actions: [analyticsSpacesLogic, ['loadSpaces']],
    })),
    actions({
        openShareToSpace: (target: ShareToSpaceTarget) => ({ target }),
        closeShareToSpace: true,
        shareToSpace: (space: AnalyticsSpace) => ({ space }),
        shareToSpaceDone: true,
    }),
    reducers({
        target: [
            null as ShareToSpaceTarget | null,
            {
                openShareToSpace: (_, { target }) => target,
                closeShareToSpace: () => null,
                shareToSpaceDone: () => null,
            },
        ],
        sharing: [false, { shareToSpace: () => true, shareToSpaceDone: () => false, closeShareToSpace: () => false }],
    }),
    listeners(({ actions, values }) => ({
        openShareToSpace: () => {
            if (!values.spaces.length && !values.spacesLoading) {
                actions.loadSpaces()
            }
        },
        shareToSpace: async ({ space }) => {
            const target = values.target
            if (!target) {
                return
            }
            try {
                const found = await api.fileSystem.list({ ref: target.ref, ...fileSystemTypeParams(target.type) })
                const entry = found.results[0]
                if (!entry) {
                    throw new Error('This item has no row in the project file system yet.')
                }
                await api.fileSystem.move(entry.id, `${space.path}/${escapePath(target.name)}`)
                lemonToast.success(`Shared into ${space.name}`)
                actions.loadSpaces()
            } catch (error) {
                lemonToast.error(error instanceof Error ? error.message : 'Could not share this item.')
            }
            actions.shareToSpaceDone()
        },
    })),
])
